mapper.select:
SELECT

FROM sessions


        AND id ILIKE CONCAT('%', #{param.id}, '%')


        AND tenant_id = #{param.tenantId}


        AND title ILIKE CONCAT('%', #{param.title}, '%')


        AND description ILIKE CONCAT('%', #{param.description}, '%')


        AND knowledge_base_id ILIKE CONCAT('%', #{param.knowledgeBaseId}, '%')


        AND max_rounds = #{param.maxRounds}


        AND enable_rewrite = #{param.enableRewrite}


        AND fallback_strategy ILIKE CONCAT('%', #{param.fallbackStrategy}, '%')


        AND fallback_response ILIKE CONCAT('%', #{param.fallbackResponse}, '%')


        AND keyword_threshold = #{param.keywordThreshold}


        AND vector_threshold = #{param.vectorThreshold}


        AND rerank_model_id ILIKE CONCAT('%', #{param.rerankModelId}, '%')


        AND embedding_top_k = #{param.embeddingTopK}


        AND rerank_top_k = #{param.rerankTopK}


        AND rerank_threshold = #{param.rerankThreshold}


        AND summary_model_id ILIKE CONCAT('%', #{param.summaryModelId}, '%')


        AND summary_parameters ILIKE CONCAT('%', #{param.summaryParameters}, '%')


        AND agent_config ILIKE CONCAT('%', #{param.agentConfig}, '%')


        AND context_config ILIKE CONCAT('%', #{param.contextConfig}, '%')


        AND created_at = #{param.createdAt}


        AND created_at >= #{param.createdAtStart}


        AND created_at <= #{param.createdAtEnd}


        AND updated_at = #{param.updatedAt}


        AND deleted_at = #{param.deletedAt}


        AND agent_id ILIKE CONCAT('%', #{param.agentId}, '%')


        AND user_id ILIKE CONCAT('%', #{param.userId}, '%')


        AND is_pinned = #{param.isPinned}


        AND pinned_at = #{param.pinnedAt}


ORDER BY id DESC
